"use strict";(self.webpackChunkdocs=self.webpackChunkdocs||[]).push([[1954],{31946:e=>{e.exports=JSON.parse('{"functions":[{"name":"declare","desc":"Declare a ValueBase-backed variable.\\n\\n**Syntax:** `observable T name = value;`\\n\\n**Emit:** `Instance.new(\\"IntValue\\"); name.Value = value`\\n\\n`int` \u2192 IntValue, `float`/`double` \u2192 NumberValue, `string` \u2192 StringValue, `bool` \u2192 BoolValue, else ObjectValue.","params":[],"returns":[],"function_type":"static","tags":["signal"],"source":{"line":25,"path":"moonwave/Observables.lua"}},{"name":"OnChange","desc":"Listen to value changes. Argument is the new `.Value`.\\n\\n**Syntax:** `name.OnChange(fn);`\\n\\n**Emit:** `name.Changed:Connect(fn)`\\n\\n```clpp\\nobservable int coins = 100;\\ncoins.OnChange(func [](int newValue) {\\n    post(\\"now \\" .: newValue);\\n});\\ncoins = 50;\\n```","params":[{"name":"handler","desc":"Listener","lua_type":"func"}],"returns":[],"function_type":"static","tags":["signal"],"source":{"line":46,"path":"moonwave/Observables.lua"}}],"properties":[],"types":[],"name":"Observables","desc":"`observable T name = value` becomes a ValueBase (`IntValue`, `NumberValue`, `StringValue`, `BoolValue`, or `ObjectValue`).\\n\\nReading or writing the identifier uses `.Value`. Assigning **fires** `Changed`.\\n`.OnChange(fn)` is `Changed:Connect(fn)`.\\n\\nFull page: [observable](/CLPP/docs/reference/observable).","source":{"line":12,"path":"moonwave/Observables.lua"}}')}}]);